package testedemesa;

public class testedemesa {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		//Leia um número inteiro e mostre o seu dobro, triplo e quádruplo.
		
		int num = 5;
		int i = 2;
		
		while(i <= 4) {
			System.out.println(num * i);
			i++;
		}

	}

}
